const input = $input.first().json.body || $input.first().json;
const clientNip = input.client_nip;
const fileName = input.file_name || input.fileName || 'unknown';
const fileContent = input.file_content || input.fileContent || input.content || '';
const fileType = fileName.split('.').pop().toLowerCase();

const isXml = fileType === 'xml' || fileContent.trim().startsWith('<?xml') || fileContent.includes('<Faktura');
const isImage = ['pdf', 'jpg', 'jpeg', 'png', 'tiff'].includes(fileType);

return [{
  json: {
    client_nip: clientNip,
    file_name: fileName,
    file_type: fileType,
    file_content: fileContent,
    processing_path: isXml ? 'xml' : 'ocr',
    source_type: 'webhook'
  }
}];

const item = $input.first().json;
const xml = item.file_content;

try {
  const extract = (tag) => {
    const match = xml.match(new RegExp(`<[^:]*:?${tag}[^>]*>([^<]+)<`));
    return match ? match[1].trim() : null;
  };
  const extractAmount = (tag) => {
    const val = extract(tag);
    return val ? parseFloat(val) : null;
  };

  // NIP validation function
  function validateNIP(nip) {
    if (!nip || nip.length !== 10 || !/^\d{10}$/.test(nip)) return false;
    const weights = [6, 5, 7, 2, 3, 4, 5, 6, 7];
    let sum = 0;
    for (let i = 0; i < 9; i++) sum += parseInt(nip[i]) * weights[i];
    return (sum % 11) === parseInt(nip[9]);
  }

  const sellerNip = extract('NIPSprzedawcy') || extract('NIP');
  const buyerNip = extract('NIPNabywcy');
  const ksefNumber = extract('NumerKSeF') || extract('KsefReferenceNumber');

  return [{
    json: {
      client_nip: item.client_nip,
      ksef_number: ksefNumber,
      invoice_number: extract('P_2') || extract('NrFaktury'),
      direction: (sellerNip === item.client_nip) ? 'sales' : 'purchase',
      seller_nip: sellerNip,
      seller_name: extract('NazwaSprzedawcy') || extract('Nazwa'),
      buyer_nip: buyerNip,
      buyer_name: extract('NazwaNabywcy'),
      net_amount: extractAmount('P_13_1'),
      vat_amount: extractAmount('P_14_1'),
      gross_amount: extractAmount('P_15'),
      currency: extract('KodWaluty') || 'PLN',
      issue_date: extract('P_1'),
      seller_nip_valid: validateNIP(sellerNip),
      buyer_nip_valid: validateNIP(buyerNip),
      raw_xml: xml,
      parse_success: true
    }
  }];
} catch (e) {
  return [{ json: { ...item, parse_success: false, parse_error: e.message } }];
}

