const item = $('Detect Document Format').first().json;
const queueId = $input.first().json.id;

// Simulated OCR result - replace with actual Claude Vision API call
return [{
  json: {
    ocr_queue_id: queueId,
    client_nip: item.client_nip,
    extracted: {
      invoice_number: null,
      seller_nip: null,
      buyer_nip: null,
      net_amount: null,
      vat_amount: null,
      gross_amount: null,
      issue_date: null
    },
    confidence_score: 0.0,
    needs_claude_api: true,
    note: 'Configure Claude Vision API HTTP Request node to extract invoice data from PDF/image'
  }
}];

const data = $input.first().json;
const confidence = data.confidence_score || 0;
const extracted = data.extracted || {};

// NIP validation
function validateNIP(nip) {
  if (!nip || nip.length !== 10 || !/^\d{10}$/.test(nip)) return false;
  const weights = [6, 5, 7, 2, 3, 4, 5, 6, 7];
  let sum = 0;
  for (let i = 0; i < 9; i++) sum += parseInt(nip[i]) * weights[i];
  return (sum % 11) === parseInt(nip[9]);
}

const sellerNipValid = validateNIP(extracted.seller_nip);
const buyerNipValid = validateNIP(extracted.buyer_nip);

// Amount consistency check
let amountsValid = true;
if (extracted.net_amount && extracted.vat_amount && extracted.gross_amount) {
  const expectedGross = Math.round((extracted.net_amount + extracted.vat_amount) * 100) / 100;
  amountsValid = Math.abs(expectedGross - extracted.gross_amount) < 0.02;
}

const isHighConfidence = confidence >= 0.85 && sellerNipValid && amountsValid;

return [{
  json: {
    ...data,
    seller_nip_valid: sellerNipValid,
    buyer_nip_valid: buyerNipValid,
    amounts_valid: amountsValid,
    high_confidence: isHighConfidence,
    ocr_status: isHighConfidence ? 'completed' : 'manual_review'
  }
}];

